import ghidra.app.script.GhidraScript; import ghidra.app.decompiler.*; import ghidra.program.model.listing.*; import ghidra.program.model.address.*; import java.io.*;
public class DecompileQheeAddresses extends GhidraScript { public void run() throws Exception { String[] a=getScriptArgs(); PrintWriter p=new PrintWriter(new FileOutputStream(a[0])); DecompInterface d=new DecompInterface(); d.openProgram(currentProgram); for(int i=1;i<a.length;i++){Address x=toAddr(a[i]); Function f=getFunctionContaining(x); if(f==null)f=getFunctionAt(x); p.println("===== "+a[i]+" "+(f==null?"NOFUNC":f.getName()+" @"+f.getEntryPoint())+" ====="); if(f!=null){DecompileResults r=d.decompileFunction(f,120,monitor); if(r!=null&&r.decompileCompleted()&&r.getDecompiledFunction()!=null)p.println(r.getDecompiledFunction().getC());}} d.dispose(); p.close(); }}
